/** @fileoverview Captures complete original cppuhelper interface/service contracts over genuine unchanged shared owners and real generated XServiceInfo headers. */
import { spawnSync } from "node:child_process";
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";
import { gzipSync } from "node:zlib";
import { unoNativeCppValueCaller } from "./uno-native-cpp-caller.mjs";
import { prepareCaseNative } from "./casefolding-native-build.mjs";
import { hash, loadUnicodeOriginal, pin, upstream } from "./rtl-ustring-native-sources.mjs";
import { originalDependency } from "./casefolding-native-libraries.mjs";

const write = process.argv.length === 3 && process.argv[2] === "--write";
const check = process.argv.length === 3 && process.argv[2] === "--check";
if (!write && !check) throw new Error("Use exactly --write or --check");
const target = "output/playwright/cppuhelper-service-native";
const fixture = "apps/office/src/cppuhelper/source/native-service-helper-cases.json";
const native = prepareCaseNative(target);
for (const path of [
  "cppu/source/typelib/typelib.cxx",
  "include/typelib/typedescription.h",
  "sal/rtl/ustring.cxx",
  "include/rtl/ustring.hxx",
  "include/o3tl/string_view.hxx",
])
  loadUnicodeOriginal(native.sources, path);
const names = ["Exception", "RuntimeException", "XInterface", "TypeClass"];
for (const name of names) {
  const relative = `com/sun/star/uno/${name}.idl`;
  mkdirSync(`${target}/idl/com/sun/star/uno`, { recursive: true });
  writeFileSync(
    `${target}/idl/${relative}`,
    loadUnicodeOriginal(native.sources, `udkapi/${relative}`),
  );
}
mkdirSync(`${target}/idl/com/sun/star/lang`, { recursive: true });
writeFileSync(
  `${target}/idl/com/sun/star/lang/XServiceInfo.idl`,
  loadUnicodeOriginal(native.sources, "udkapi/com/sun/star/lang/XServiceInfo.idl"),
);
native.run(
  "output/playwright/task39-native-types/cppumaker",
  [
    "-nD",
    "-T",
    "com.sun.star.lang.XServiceInfo",
    "-O",
    resolve(`${target}/generated`),
    pathToFileURL(resolve(`${target}/idl`)).href,
  ],
  "original-service-type-generation",
);
for (const extension of ["hdl", "hpp"]) {
  const path = `${target}/generated/com/sun/star/lang/XServiceInfo.${extension}`;
  native.manifest.generatedHashes[path] = hash(readFileSync(path));
}
